/// <reference types="vitest/config" />
import { fileURLToPath } from 'node:url';
import { getViteConfig } from 'astro/config';

// Astro's Vite config, so tests can import and render real .astro components
// (test/fixtures) with the Container API, exactly as the preview server does.
export default getViteConfig(
  {
    resolve: {
      alias: {
        // Generated by the integration during a real build; tests get a
        // double they can fill in (test/fixtures/virtual-preview-islands.ts).
        'virtual:preview-islands': fileURLToPath(new URL('./test/fixtures/virtual-preview-islands.ts', import.meta.url)),
      },
    },
    test: {
      include: ['src/**/*.test.ts', 'test-editor/**/*.test.ts'],
      restoreMocks: true,
      environmentOptions: {
        happyDOM: {
          // The editor sets iframe.src; never let the test DOM fetch it.
          settings: { disableIframePageLoading: true },
        },
      },
      coverage: {
        provider: 'v8',
        reporter: ['text', 'html'],
        include: ['src/**', 'test-editor/**'],
        exclude: [
          '**/*.test.ts',
          '**/*.d.ts',
          'src/types.ts',
          // Glue scripts with top-level side effects: covered by the
          // end-to-end suite, not unit tests.
          'src/build.ts',
          'src/start.ts',
          'src/client/bridge-entry.ts',
          'test-editor/editor.astro',
        ],
      },
    },
  },
  // Astro config for the test run: no site, just the compiler.
  { root: fileURLToPath(new URL('.', import.meta.url)), logLevel: 'error' },
);
